:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0e6d2;
  --primary: #6c5ce7;
  --secondary: #00cec9;
  --accent: #fd79a8;
  --hunger: #e17055;
  --happiness: #fdcb6e;
  --energy: #00b894;
  --border-radius: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

.pet-container {
  display: flex;
  justify-content: center;
  padding: 8px 0;
}

.pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.pixel {
  position: absolute;
  background: var(--accent);
  border-radius: 2px;
}

.body {
  width: 80px;
  height: 80px;
  left: 20px;
  top: 30px;
  background: var(--primary);
  border-radius: 8px;
}

.ear {
  width: 24px;
  height: 24px;
  top: 10px;
  background: var(--primary);
  border-radius: 4px;
}

.ear.left {
  left: 20px;
}

.ear.right {
  right: 20px;
}

.eye {
  width: 12px;
  height: 12px;
  background: #fff;
  border-radius: 50%;
  top: 55px;
}

.eye.left {
  left: 40px;
}

.eye.right {
  right: 40px;
}

.nose {
  width: 16px;
  height: 8px;
  background: var(--accent);
  border-radius: 4px;
  top: 75px;
  left: 52px;
}

.mouth {
  width: 24px;
  height: 8px;
  background: var(--accent);
  border-radius: 0 0 12px 12px;
  top: 88px;
  left: 48px;
}

.mood {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--secondary);
  transition: color 0.3s ease;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 12px;
}

.stat-label {
  width: 80px;
  text-align: left;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text);
}

.bar-bg {
  flex: 1;
  height: 20px;
  background: #3d3d5c;
  border-radius: 10px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 0%;
  border-radius: 10px;
  transition: width 0.4s ease;
}

.bar-fill.hunger {
  background: var(--hunger);
}

.bar-fill.happiness {
  background: var(--happiness);
}

.bar-fill.energy {
  background: var(--energy);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 90px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 700;
  font-family: var(--font);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.2s ease, background 0.2s ease;
  color: #fff;
  background: var(--primary);
  box-shadow: 0 4px 0 #4a3f9e;
}

.btn:hover {
  background: #7d6ef0;
  box-shadow: 0 4px 0 #4a3f9e, 0 0 0 2px #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #4a3f9e;
}

.btn.feed {
  background: var(--hunger);
  box-shadow: 0 4px 0 #b85c3a;
}

.btn.feed:hover {
  background: #f08a6a;
  box-shadow: 0 4px 0 #b85c3a, 0 0 0 2px #fff;
}

.btn.feed:active {
  box-shadow: 0 0 0 #b85c3a;
}

.btn.play {
  background: var(--happiness);
  color: #1e1e2f;
  box-shadow: 0 4px 0 #c9a63a;
}

.btn.play:hover {
  background: #ffe08a;
  box-shadow: 0 4px 0 #c9a63a, 0 0 0 2px #fff;
}

.btn.play:active {
  box-shadow: 0 0 0 #c9a63a;
}

.btn.sleep {
  background: var(--energy);
  box-shadow: 0 4px 0 #008a6e;
}

.btn.sleep:hover {
  background: #1ae0b0;
  box-shadow: 0 4px 0 #008a6e, 0 0 0 2px #fff;
}

.btn.sleep:active {
  box-shadow: 0 0 0 #008a6e;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  .stat-label {
    width: 70px;
    font-size: 0.85rem;
  }
  .btn {
    min-width: 70px;
    padding: 10px 12px;
    font-size: 0.9rem;
  }
}

const state = {
  hunger: 80,
  happiness: 70,
  energy: 90
};

const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  hungerBar.parentElement.setAttribute('aria-valuenow', state.hunger);
  happinessBar.style.width = state.happiness + '%';
  happinessBar.parentElement.setAttribute('aria-valuenow', state.happiness);
  energyBar.style.width = state.energy + '%';
  energyBar.parentElement.setAttribute('aria-valuenow', state.energy);

  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 70) mood = 'Happy';
  else if (avg >= 40) mood = 'Okay';
  else mood = 'Sad';
  moodEl.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
